def _backend_check(self, user, now_ms, count_fault=True):
    """老化前的后端健康检查，O(1) 时空。

    截至与 retry_at 均到（含无故障）则清该用户退避并返回；故障中且
    retry_at 已到则 n 加一、retry_at = now_ms+min(100*2**(n-1), 1600)
    并抛 BackendError(retry_at)，计一次“故障”失败；retry_at 未到则
    n 不变，抛 BackendError(retry_at)，计一次“退避”失败。本方法仅由
    新 key 首次路径调用，重放不到达，故每次抛错恰计一次。count_fault
    为 False 时（batch_online 批内检查）只维护退避，不计 fault_stats
    失败（其口径仅含 do 与 capacity）。
    """
    n, retry_at = self._backoff.get(user, (0, 0))
    if now_ms >= self._fault_until and now_ms >= retry_at:
        # 健康：清该用户退避（无则空操作）。
        self._backoff.pop(user, None)
        return
    if now_ms >= retry_at:
        # 故障中且退避到期：n 加一，指数退避重算 retry_at（封顶 1600）。
        n += 1
        retry_at = now_ms + min(100 * 2 ** (n - 1), 1600)
        self._backoff[user] = (n, retry_at)
        if count_fault:
            self._fault_fail[0] += 1
    else:
        # 退避未到期：n 不变。
        if count_fault:
            self._fault_fail[1] += 1
    raise BackendError(retry_at)

def _capacity_counts(self, user=None):
    """非下线会话计数（排队项不计数）：返回 (总数, 该用户数)。"""
    total_count = 0
    user_count = 0
    for session in self._sessions.values():
        if session["state"] != _STATE_OFFLINE:
            total_count += 1
            if user is not None and session["user"] == user:
                user_count += 1
    return total_count, user_count

def _template_occupancy(self, template_id):
    """模板当前占用：绑定该模板用户的在线加挂起会话数，O(S)/O(1)。"""
    occupancy = 0
    for session in self._sessions.values():
        if (
            session["state"] != _STATE_OFFLINE
            and self._user_templates.get(session["user"]) == template_id
        ):
            occupancy += 1
    return occupancy

def _queue_effective(self, user, applied, now_ms):
    """队项在 now_ms 的有效优先级（与推进同口径）：
    min(1000, 基础+max(0,now_ms-申请时刻)//1000)，基础取此刻用户绑定
    模板的排队优先级、未绑定为 0。O(1) 时空。"""
    template_id = self._user_templates.get(user)
    base = (
        self._templates[template_id][5]
        if template_id is not None
        else 0
    )
    return min(
        _MAX_EFFECTIVE_PRIORITY,
        base + max(0, now_ms - applied) // 1000,
    )

def _template_limit_of(self, user):
    """用户所绑模板的并发会话上限；未绑定或模板无上限（0）返回 0。"""
    template_id = self._user_templates.get(user)
    if template_id is None:
        return 0
    return self._templates[template_id][4]

def _pool_is_exhausted(self, pool_id, now_ms):
    """池耗尽演练判定，O(1) 时空：注入后 now_ms < 截至即视为无可分配
    地址，到刻（含同刻）自动正常；不演练或已恢复无记录。只读不改态。"""
    until = self._pool_fault.get(pool_id)
    return until is not None and now_ms < until

def _candidate_pools(self, user):
    """user 自动取址的候选池序列（按优先序），O(1) 时空。

    绑定模板且该模板配置了“模板地址池”序列时返回配置序列
    （1..32 个互异池标识）；未绑定模板或模板未列序列时仅 default 池，
    以保持旧配置与未绑定用户的行为。
    """
    return self._candidate_pools_for(
        user, self._user_templates, self._template_pool_order
    )

@staticmethod
def _candidate_pools_for(user, user_templates, template_pool_order):
    """同 _candidate_pools，但绑定与模板池序列由调用方给出（供容量热
    均衡在候选配置视图上演算）。"""
    template_id = user_templates.get(user)
    if template_id is not None:
        sequence = template_pool_order.get(template_id)
        if sequence is not None:
            return sequence
    return (_DEFAULT_POOL_ID,)

@staticmethod
def _pool_candidate_address(pool, user):
    """单池对 user 的可取址窥视，O(1) 时空，不弹堆、不改态。

    该用户在本池有专属静态地址时：未租用即返回该静态址，已被任一会话
    租用（含其自身另一会话）返回 None 且不回落动态址；否则返回动态空闲
    堆顶（不弹出），无动态空闲址返回 None。
    """
    static_ip = pool.static.get(user)
    if static_ip is None:
        return pool.free[0] if pool.free else None
    if static_ip in pool.leases:
        return None
    return static_ip

def _select_address(self, user, now_ms):
    """按候选池优先序确定性选池取址，只读窥视不改态，O(P) 时间 O(1) 空间。

    候选池序见 _candidate_pools（至多 32 个）。依次跳过：处于有效耗尽
    故障（now_ms < 注入截至）的池、没有可取动态地址且该用户在本池无可用
    专属静态址的池（无动态址，或专属静态址正被占用）。首个可取址池返回
    (pool_id, ip)（动态仅窥堆顶、不弹出，落库由 _commit_session 完成）。
    全部不可用时返回 (pool_id, None)，pool_id 为序列中最后一个现存池；
    候选序列无任何现存池（零池模式且序列仅 default）时返回 (None, None)。
    """
    last_pool_id = None
    for pool_id in self._candidate_pools(user):
        pool = self._pools.get(pool_id)
        if pool is None:
            continue
        last_pool_id = pool_id
        if self._pool_is_exhausted(pool_id, now_ms):
            continue
        ip_int = self._pool_candidate_address(pool, user)
        if ip_int is not None:
            return pool_id, ip_int
    return last_pool_id, None

def _candidate_v6_pools(self, user):
    """user 的 IPv6 后备前缀池序列（按模板 IPv6 池配置优先序，至多 32）；
    未绑定模板或模板未配置引用时返回空 tuple，该用户即保持纯 IPv4。"""
    return self._candidate_v6_pools_for(
        user, self._user_templates, self._template_v6_pool_order
    )

@staticmethod
def _candidate_v6_pools_for(user, user_templates, template_v6_pool_order):
    """同 _candidate_v6_pools，但绑定与模板 v6 序列由调用方给出（供容量
    热均衡在候选配置视图上演算）。"""
    template_id = user_templates.get(user)
    if template_id is None:
        return ()
    return template_v6_pool_order.get(template_id, ())

def _select_v6_prefix(self, user):
    """按后备前缀池优先序确定性选取委派前缀，只读窥视不改态。

    静态绑定优先：首个候选池中该用户的专属静态前缀空闲即取之；否则在
    首个含空闲动态前缀的后备池中取数值最小者。某池静态前缀被占用或动态
    耗尽时继续下一后备池；全部后备池耗尽返回 None（无后备配置返回
    None）。单次 O(P log L)，P≤32、L 为活动前缀租约数（归还堆堆顶
    O(1)，游标推进总计 O(R+S) 摊薄于各次选择）。
    """
    for pool_id in self._candidate_v6_pools(user):
        v6_pool = self._v6_pools.get(pool_id)
        if v6_pool is None:
            continue
        prefix = v6_pool.peek(user)
        if prefix is not None:
            return pool_id, prefix
    return None

def _commit_v6(self, user, pool_id, prefix, sid):
    """在选定前缀池中登记前缀租约（静态优先已由 _select_v6_prefix 保证）：
    动态前缀弹/推进空闲结构，静态前缀仅登记。与 IPv4 落库同一事务。"""
    v6_pool = self._v6_pools[pool_id]
    if v6_pool.static.get(user) == prefix:
        v6_pool.leases[prefix] = sid
    else:
        v6_pool.allocate_dynamic(prefix)
        v6_pool.leases[prefix] = sid

def _sim_v6_state(self, relevant_pool_ids, do_age=False, now_ms=0):
    """构建只读演算用的 v6 选择态，不按聚合池展开、不触碰实例。

    每个相关前缀池一项 [归还堆副本, 游标副本, 模拟租用集]：归还堆仅含
    历史归还的动态前缀（至多 L 项），游标为真实池首个未派发块，模拟
    租用集初值为真实在租前缀集；do_age=True 时老化到期（期限或 v6 租期
    <= now_ms）在线会话释出的动态前缀入归还堆副本、静态前缀仅移出模拟
    租用集。选择规则与 _V6PrefixPool.peek/allocate_dynamic 同构。
    总空间 O(L+R+S)（外加一次 O(S) 会话扫描）。
    """
    sims = {}
    for pool_id in relevant_pool_ids:
        pool = self._v6_pools.get(pool_id)
        if pool is None:
            continue
        sims[pool_id] = [
            list(pool.free_heap),
            pool.cursor,
            set(pool.leases),
        ]
    if do_age:
        for session in self._sessions.values():
            v6_first = session.get("v6")
            if (
                v6_first is None
                or session["state"] != _STATE_ONLINE
            ):
                continue
            pool_id = session["v6_pool"]
            state = sims.get(pool_id)
            if state is None:
                continue
            aging = (
                session["deadline"] <= now_ms
                or session["v6_lease"] <= now_ms
            )
            if not aging:
                continue
            state[2].discard(v6_first)
            pool = self._v6_pools[pool_id]
            if v6_first not in pool.static_ips:
                heapq.heappush(state[0], v6_first)
    return sims

def _sim_v6_try(self, user, candidate_ids, sims):
    """模拟态下按后备池序尝试委派前缀；成功即占用模拟态并返回 True。

    候选序列为空（未绑定模板或模板未配置 IPv6 池的纯 IPv4 用户）恒为
    True 且不占用任何前缀。静态优先（专属静态前缀被真实或模拟租用即试
    下一后备池），否则取数值最小空闲动态前缀（归还堆顶与游标之较小者）；
    全部后备池耗尽返回 False。单次 O(P log L)，P≤32。
    """
    if not candidate_ids:
        return True
    for pool_id in candidate_ids:
        state = sims.get(pool_id)
        if state is None:
            continue
        pool = self._v6_pools[pool_id]
        heap_copy, cursor, leased = state
        static_prefix = pool.static.get(user)
        if static_prefix is not None:
            if static_prefix in leased:
                continue
            leased.add(static_prefix)
            return True
        heap_top = heap_copy[0] if heap_copy else None
        sim_cursor = cursor
        while (
            sim_cursor <= pool.last
            and (
                sim_cursor in pool.reserved
                or sim_cursor in pool.static_ips
            )
        ):
            sim_cursor += pool.step
        if heap_top is None and sim_cursor > pool.last:
            continue
        if heap_top is None or sim_cursor < heap_top:
            chosen = sim_cursor
            state[1] = sim_cursor + pool.step
        else:
            chosen = heapq.heappop(heap_copy)
        leased.add(chosen)
        return True
    return False

def _release_v6_only(self, session):
    """仅释放 IPv6 前缀而保留 IPv4 地址：用于建立事务中取得前缀后失败
    的回滚（撤销本次已取得的 IPv6 前缀，不留半委派租约）。"""
    v6_first = session.get("v6")
    if v6_first is None:
        return
    v6_pool = self._v6_pools[session["v6_pool"]]
    del v6_pool.leases[v6_first]
    if v6_first not in v6_pool.static_ips:
        v6_pool.release_dynamic(v6_first)
    session["v6"] = None
    session["v6_pool"] = None
    session["v6_lease"] = 0

